describe('ToolRegistry', () => {
  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_tool',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_tool/);
  });

  it('validates input against the resolved definition schema before calling the executor', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {
        name: 'test_tool',
        description: 'A test tool',
        inputSchema: {
          type: 'object',
          properties: {requiredField: {type: 'string'}},
          required: ['requiredField'],
        },
      },
      async () => {
        calls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('test_tool', {});

    expect({
      calls,
      result: response.result,
    }).toEqual({
      calls: 0,
      result: expect.stringMatching(/required.*requiredField/i),
    });
  });

  it('passes valid input with unlisted extra properties through to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    let capturedInput: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'extra_tool',
        description: 'd',
        inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
      },
      async input => {
        capturedInput = input;
        return 'ok';
      }
    );

    await registry.execute('extra_tool', {a: 'val', extra: 123});

    expect(capturedInput).toEqual({a: 'val', extra: 123});
  });

  it('throws Unknown tool error for unregistered tool name', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('unknown', {})).rejects.toThrow(/Unknown tool: unknown/);
  });

  it('compiles a static tool schema once and reuses it across multiple calls', async () => {
    const registry = new ToolRegistry();
    const compileSpy = jest.spyOn(Ajv.prototype, 'compile');

    registry.register(
      {
        name: 'static_tool',
        description: 'd',
        inputSchema: {type: 'object', properties: {p: {type: 'string'}}},
      },
      async () => 'ok'
    );

    const {calls} = compileSpy.mock;
    const initialCompileCount = calls.length;

    await registry.execute('static_tool', {p: 'a'});
    await registry.execute('static_tool', {p: 'b'});

    expect(calls.length).toBe(initialCompileCount);
    compileSpy.mockRestore();
  });

  it('caches dynamic validators by schema object reference in a WeakMap', async () => {
    const registry = new ToolRegistry();
    const compileSpy = jest.spyOn(Ajv.prototype, 'compile');
    const schema = {type: 'object', properties: {p: {type: 'string'}}};

    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'd',
        inputSchema: schema,
      }),
      async () => 'ok'
    );

